const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
lines.forEach((line, i) => {
  const s = line.replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') return
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(s)
  const a = parseAddr(m[1])
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${m[1]}`)
  const k = keyOf(a.col, a.row)
  if (cells.has(k)) fail(`error: line ${i + 1}: cell ${m[1].toUpperCase()} is declared twice`)
  cells.set(k, { col: a.col, row: a.row, content: m[2] })
